using UnityEngine;
using UnityEditor;
using System.Linq;

internal class CommandScript : IReadonlyRunCommand
{
    public void Execute(ReadonlyExecutionResult result)
    {
        // Find all InventoryItem assets
        string[] guids = AssetDatabase.FindAssets("t:InventoryItem");
        result.Log("Total InventoryItems found: {0}", guids.Length);

        int buildableCount = 0;
        foreach (string guid in guids)
        {
            string path = AssetDatabase.GUIDToAssetPath(guid);
            InventoryItem item = AssetDatabase.LoadAssetAtPath<InventoryItem>(path);
            if (item != null && item.buildable)
            {
                buildableCount++;
                string prefabName = item.prefab != null ? item.prefab.name : "null";
                string prefabPath = item.prefab != null ? AssetDatabase.GetAssetPath(item.prefab) : "null";
                result.Log("Buildable Item: '{0}' (Asset: {1}) -> Prefab: '{2}' ({3})", item.name, path, prefabName, prefabPath);
            }
        }
        result.Log("Total buildable items: {0}", buildableCount);

        // Also check ItemManager prefabs / scenes
        string[] itemManagerGuids = AssetDatabase.FindAssets("t:Prefab ItemManager");
        foreach (string guid in itemManagerGuids)
        {
            result.Log("ItemManager prefab: {0}", AssetDatabase.GUIDToAssetPath(guid));
        }
    }
}

